import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, Link } from 'react-router-dom'; 
import "./RiverDashboard.css";
import dataloggerImage from "../assets/datalogger.png";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const DEBUG_API = `${API_BASE_URL}/api/weather/debug-read-s3`;

const RiverDashboard = () => {
  const navigate = useNavigate();
  
  const [forecastData, setForecastData] = useState([]);
  const [limeData, setLimeData] = useState([]);
  const [realTimeLevel, setRealTimeLevel] = useState("--"); 
  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState("");
  const [currentTime, setCurrentTime] = useState(new Date());

  const getStatus = (level) => {
    const val = parseFloat(level);
    if (isNaN(val)) return { label: "--", class: "status-unknown", color: "#ccc", icon: "fa-question-circle" };
    if (val < 3) return { label: "Normal", class: "status-normal", color: "#10b981", icon: "fa-check-circle" }; 
    if (val < 8.0) return { label: "Caution", class: "status-caution", color: "#f59e0b", icon: "fa-exclamation-circle" }; 
    return { label: "Warning", class: "status-critical", color: "#ef4444", icon: "fa-radiation-alt" }; 
  };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const loadAllData = async () => {
      try {
        const [forecastRes, realTimeRes, limeRes] = await Promise.all([
          axios.get(DEBUG_API, { params: { file: "forecast_output.csv", _t: Date.now() } }),
          axios.get(DEBUG_API, { params: { file: "hourly_averages/STA_01_MASTER_LOG.csv", _t: Date.now() } }),
          axios.get(DEBUG_API, { params: { file: "lime_short_sentences_and_labels.txt", _t: Date.now() } })
        ]);

        // Parse Forecast
        if (forecastRes.data?.status === "success") {
          const parsed = forecastRes.data.preview.map(line => {
            const cols = line.split(",");
            const val = cols[cols.length - 1]?.trim();
            return { level: parseFloat(val).toFixed(2), status: getStatus(val) };
          }).filter(item => !isNaN(item.level));
          setForecastData(parsed);
          setLastUpdated(new Date().toLocaleTimeString("en-IN", {hour: '2-digit', minute:'2-digit'}));
        }

        // Parse Real-time
        if (realTimeRes.data?.status === "success") {
          const lines = realTimeRes.data.preview;
          const lastLine = lines[lines.length - 1].split(",");
          setRealTimeLevel(parseFloat(lastLine[lastLine.length - 1]).toFixed(2));
        }

        // Parse LIME
        if (limeRes.data?.status === "success") setLimeData(limeRes.data.preview);

      } catch (err) {
        console.error("Dashboard Sync Error:", err);
      } finally {
        setLoading(false);
      }
    };

    loadAllData();
    const interval = setInterval(loadAllData, 60000);
    return () => clearInterval(interval);
  }, []);

  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentStatus = getStatus(realTimeLevel !== "--" ? realTimeLevel : 0);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Syncing Hydrological Data...</p></div>;

  return (
    <div className="rd-advanced-page">
      <style>{`:root { --hero-bg-image: url(${dataloggerImage}); }`}</style>
      
      <header className="rd-navbar">
        <div className="rd-container-inner rd-flex-between">
          <Link to="/" className="rd-logo">Periyar River <span>Flood Watch</span></Link>
          <div className="rd-nav-links">
            <button onClick={() => navigate('/weather-home')}>Back to Home</button>
          </div>
        </div>
      </header>

      <section className="rd-hero-fullscreen">
        <div className="hero-overlay-gradient"></div>
        <div className="hero-content-wrapper">
          <div className="hero-pill">Real-Time Station Monitoring</div>
          <h1 className="hero-main-title">River Hydrology Dashboard</h1>
          <p className="hero-sub-text">Advanced AI forecasting for the Kalady region, providing 6-hour predictive water level insights.</p>
          
          <div className={`rd-status-card-top ${currentStatus.class}`}>
            <i className={`fas ${currentStatus.icon}`} style={{color: currentStatus.color}}></i>
            <div>
              <span className="status-label">Current Condition</span>
              <h3 className="status-val">{currentStatus.label}</h3>
            </div>
          </div>
        </div>
      </section>

      <main className="rd-content-container">
        <div className="rd-stats-grid">
          <div className="rd-glass-card">
            <div className="card-top"><span>Live Level</span><i className="fas fa-ruler-vertical"></i></div>
            <div className="big-stat">{realTimeLevel}<small>m</small></div>
            <div className="card-foot">Last Updated: {lastUpdated}</div>
          </div>

          <div className="rd-glass-card">
            <div className="card-top"><span>1Hr Forecast</span><i className="fas fa-bolt"></i></div>
            <div className="big-stat" style={{color: nextHour.status.color}}>{nextHour.level}<small>m</small></div>
            <div className="card-foot">AI Confidence: 98.5%</div>
          </div>

          <div className="rd-glass-card">
            <div className="card-top"><span>Station Time</span><i className="far fa-clock"></i></div>
            <div className="big-stat-time">{currentTime.toLocaleTimeString('en-IN', {timeStyle: 'short'})}</div>
            <div className="card-foot">{currentTime.toLocaleDateString('en-IN', {dateStyle: 'medium'})}</div>
          </div>
        </div>

        <div className="rd-split-layout">
          <section className="rd-dashboard-section">
            <div className="section-header">
              <h3><i className="fas fa-chart-line"></i> 6-Hour Water Level Projection</h3>
              <p className="section-subtitle">Click nodes to view localized impact analysis</p>
            </div>
            
            <div className="rd-timeline-scroll">
              <div className="rd-timeline-flex">
                {forecastData.slice(0, 6).map((data, index) => (
                  <div key={index} className="rd-time-node clickable-node" onClick={() => navigate(`/flood-analysis?level=${data.level}`)}>
                    <span className="time-label">+{index + 1}h</span>
                    <div className="bar-track">
                      <div className="bar-fill" style={{ height: `${Math.min((parseFloat(data.level) / 10) * 100, 100)}%`, backgroundColor: data.status.color }}></div>
                    </div>
                    <span className="val-label">{data.level}m</span>
                    <div className="impact-chip" style={{background: `${data.status.color}20`, color: data.status.color}}>{data.status.label}</div>
                  </div>
                ))}
              </div>
            </div>
          </section>

          <section className="rd-dashboard-section">
            <div className="section-header">
              <h3><i className="fas fa-robot"></i> AI Explainability (LIME)</h3>
              <p className="section-subtitle">Factor analysis contributing to the current forecast</p>
            </div>
            <div className="rd-lime-list">
              {limeData.length > 0 ? limeData.slice(0, 4).map((line, index) => (
                <div key={index} className="rd-lime-item">
                  <div className="lime-index">H+{index + 1}</div>
                  <p className="lime-desc">{line.replace(/\[.*?\]/, "").trim()}</p>
                </div>
              )) : <p>Generating insights...</p>}
            </div>
          </section>
        </div>
      </main>

      <footer className="rd-footer-advanced">
        <div className="rd-container-inner footer-grid">
          <div className="footer-brand">
            <h4>Periyar Flood Watch</h4>
            <p>A specialized hydrological monitoring initiative by the Center for AI-IoT Innovations at Adi Shankara Institute.</p>
          </div>
          <div className="footer-contact">
            <h5>Contact Station</h5>
            <p>Kalady, Ernakulam, Kerala</p>
            <p>aiiot@adishankara.ac.in</p>
          </div>
        </div>
        <div className="footer-copyright">
          &copy; {new Date().getFullYear()} ASIET AI-IoT.
        </div>
      </footer>
    </div>
  );
};

export default RiverDashboard;
